actions.script:
if (organizationPartyId != ec.user.getPreference('ACTIVE_ORGANIZATION')) { ec.message.addError('Select your active organization.'); return }
if (fromFacilityId == toFacilityId) { ec.message.addError('Choose two different warehouses.'); return }
for (id in [fromFacilityId, toFacilityId]) {
    def f = ec.entity.find('mantle.facility.Facility').condition('facilityId', id).one()
    if (!f || f.ownerPartyId != organizationPartyId) ec.message.addError('Both warehouses must belong to your active organization.')
}

def prod = ec.entity.find('mantle.product.Product').condition('productId', productId).one()
if (!prod || prod.ownerPartyId != guard.organizationPartyId) { ec.message.addError('Choose a product from your active organization.'); return }
if (prod.productTypeEnumId != 'PtAsset') { ec.message.addError('Only physical products can be transferred between warehouses.'); return }
def ids = (serialNumbers ?: []).findAll { it }.collect { it.toString() }
if (ids.size() != ids.toSet().size()) { ec.message.addError('A serial number can only be selected once.'); return }
if (ids && prod.enableSerialTracking != 'Y') { ec.message.addError('This product does not track serial numbers.'); return }
if (ids) quantity = ids.size() as BigDecimal
if (quantity == null || quantity.signum() <= 0) { ec.message.addError('Quantity to send must be greater than zero.'); return }
if (prod.enableSerialTracking == 'Y' && quantity.stripTrailingZeros().scale() > 0) { ec.message.addError('Serial-tracked quantities must be whole numbers.'); return }
def price = unitAmount != null ? unitAmount : (prod.mrpAmount ?: 0G)
if (price < 0) { ec.message.addError('Unit amount cannot be negative.'); return }
def picked = []
for (id in ids) {
    def sn = ec.entity.find('zenith.erp.inventory.ProductSerialNumber').condition('serialNumberId', id).one()
    def used = ec.entity.find('zenith.erp.inventory.StockTransferItemSerial').condition('stockTransferId', stockTransferId).condition('serialNumberId', id).count()
    if (!sn || sn.productId != productId || sn.facilityId != guard.transfer.fromFacilityId || sn.statusId != 'SnInStock' || used) ec.message.addError('Selected serials must be available at the sender and unused in this transfer.')
    else picked.add(sn)
}
def source = null
if (batchNumber) {
    source = ec.entity.find('mantle.product.asset.Asset').condition('ownerPartyId', guard.organizationPartyId).condition('productId', productId)
        .condition('facilityId', guard.transfer.fromFacilityId).condition('assetTypeEnumId', 'AstTpInventory').condition('batchNumber', batchNumber)
        .condition('quantityOnHandTotal', org.moqui.entity.EntityCondition.GREATER_THAN_EQUAL_TO, quantity)
        .condition('availableToPromiseTotal', org.moqui.entity.EntityCondition.GREATER_THAN_EQUAL_TO, quantity).orderBy('expiryDate,assetId').one()
    if (!source || prod.enableBatchTracking != 'Y') ec.message.addError('Choose an in-stock batch for this product at the sender.')
}
if (ec.message.hasError()) return
def created = ec.service.sync().name('create#zenith.erp.inventory.StockTransferItem').parameters([
    stockTransferId:stockTransferId, productId:productId, quantity:quantity, unitAmount:price,
    batchNumber:batchNumber ?: null, fromAssetId:source?.assetId]).call()
transferItemSeqId = created.transferItemSeqId
for (sn in picked) ec.service.sync().name('create#zenith.erp.inventory.StockTransferItemSerial').parameters([
    stockTransferId:stockTransferId, transferItemSeqId:transferItemSeqId, serialNumberId:sn.serialNumberId, serialNumber:sn.serialNumber]).call()

def prod = ec.entity.find('mantle.product.Product').condition('productId', line.productId).one()
if (prod?.enableSerialTracking == 'Y') {
    if (quantityReceived.stripTrailingZeros().scale() > 0) { ec.message.addError('Serial-tracked quantities must be whole numbers.'); return }
    def picked = ec.entity.find('zenith.erp.inventory.StockTransferItemSerial').condition('stockTransferId', stockTransferId).condition('transferItemSeqId', transferItemSeqId).list()
    def ids = (receivedSerialNumbers ?: []).findAll { it }.collect { it.toString() }.toSet()
    if (quantityReceived == line.quantity && !ids) ids = picked.collect { it.serialNumberId }.toSet()
    if (ids.size() != quantityReceived.intValueExact() || !picked.collect { it.serialNumberId }.containsAll(ids)) {
        ec.message.addError('Select exactly the serial numbers that arrived; use zero with no selection if none arrived.'); return
    }
    for (sn in picked) { sn.received = ids.contains(sn.serialNumberId) ? 'Y' : 'N'; sn.update() }
}
line.quantityReceived = quantityReceived
line.update()

def stx = ec.entity.find('zenith.erp.inventory.StockTransfer').condition('stockTransferId', stockTransferId).one()
if (stx.ewayBillRequired == 'Y' && (!stx.transporterGstin || !stx.vehicleNumber)) { ec.message.addError('E-Way Bill is required: enter transporter GSTIN and vehicle number before shipping.'); return }
def items = ec.entity.find('zenith.erp.inventory.StockTransferItem').condition('stockTransferId', stockTransferId).orderBy('transferItemSeqId').list()
if (!items) { ec.message.addError('Add at least one product before shipping.'); return }
// Serialize competing transfers at the source; assets and serials are also locked.
ec.entity.find('mantle.facility.Facility').condition('facilityId', stx.fromFacilityId).forUpdate(true).one()
def assets = ec.entity.find('mantle.product.asset.Asset').condition('ownerPartyId', guard.organizationPartyId)
    .condition('facilityId', stx.fromFacilityId).condition('assetTypeEnumId', 'AstTpInventory').orderBy('assetId').forUpdate(true).list()
def remaining = assets.collectEntries { [(it.assetId): [(it.quantityOnHandTotal ?: 0G), (it.availableToPromiseTotal ?: 0G)].min()] }
def capacity = assets.groupBy { it.productId }.collectEntries { product, lots ->
    [(product): [(lots.sum { it.quantityOnHandTotal ?: 0G } ?: 0G), (lots.sum { it.availableToPromiseTotal ?: 0G } ?: 0G)].min()]
}
def allocations = [:]; def serialPicks = [:]; def usedSerials = new HashSet()
for (li in items) {
    def prod = ec.entity.find('mantle.product.Product').condition('productId', li.productId).one()
    def qty = li.quantity ?: 0G
    if (!prod || prod.ownerPartyId != guard.organizationPartyId || prod.productTypeEnumId != 'PtAsset' || qty <= 0 || (li.unitAmount ?: 0G) < 0) { ec.message.addError('Every line must contain your own physical product, a positive quantity and a non-negative unit amount.'); continue }
    if ((capacity[li.productId] ?: 0G) < qty) ec.message.addError('Not enough unreserved stock for ' + prod.productName + ' across all source lots and transfer lines.')
    capacity[li.productId] = (capacity[li.productId] ?: 0G) - qty
    def candidates = assets.findAll { it.productId == li.productId && remaining[it.assetId] > 0 }
    if (prod.enableBatchTracking == 'Y') {
        candidates = candidates.findAll { it.batchNumber && (!li.batchNumber || it.batchNumber == li.batchNumber) && (!li.fromAssetId || it.assetId == li.fromAssetId) }
            .sort { x, y -> (x.expiryDate?.time ?: Long.MAX_VALUE) <=> (y.expiryDate?.time ?: Long.MAX_VALUE) ?: x.assetId <=> y.assetId }
        candidates = candidates.findAll { remaining[it.assetId] >= qty }.take(1)
    }
    def needed = qty; def parts = []
    for (asset in candidates) {
        def take = [remaining[asset.assetId], needed].min()
        if (take <= 0) continue
        parts.add([asset:asset, quantity:take]); remaining[asset.assetId] -= take; needed -= take
        if (needed == 0G) break
    }
    if (needed > 0) ec.message.addError('Not enough unreserved stock for ' + prod.productName + ' at the sender (including other lines in this transfer).')
    allocations[li.transferItemSeqId] = parts
    if (prod.enableSerialTracking == 'Y') {
        if (qty.stripTrailingZeros().scale() > 0) { ec.message.addError('Serial-tracked quantities must be whole numbers.'); continue }
        def rows = ec.entity.find('zenith.erp.inventory.StockTransferItemSerial').condition('stockTransferId', stockTransferId).condition('transferItemSeqId', li.transferItemSeqId).list()
        def sns = ec.entity.find('zenith.erp.inventory.ProductSerialNumber').condition('productId', li.productId)
            .condition('facilityId', stx.fromFacilityId).condition('statusId', 'SnInStock').orderBy('serialNumberId').forUpdate(true).list()
        if (rows) sns = sns.findAll { rows.collect { it.serialNumberId }.contains(it.serialNumberId) }
        else sns = sns.findAll { !usedSerials.contains(it.serialNumberId) }.take(qty.intValueExact())
        if (sns.size() != qty.intValueExact() || sns.any { usedSerials.contains(it.serialNumberId) }) ec.message.addError('Selected serial numbers are no longer available at the sender.')
        if (prod.enableBatchTracking == 'Y' && parts && sns.any { it.batchNumber != parts[0].asset.batchNumber }) ec.message.addError('Selected serials must belong to the chosen batch.')
        usedSerials.addAll(sns.collect { it.serialNumberId }); serialPicks[li.transferItemSeqId] = [serials:sns, hadPicks:!!rows]
    }
}
if (ec.message.hasError()) return
stx.statusId = 'StxInTransit'; stx.update()
for (li in items) {
    for (part in allocations[li.transferItemSeqId]) ec.service.sync().name('zenith.inventory.StockTransferServices.move#StockTransferAsset')
        .parameters([stockTransferId:stockTransferId, assetId:part.asset.assetId, quantityDiff:-part.quantity, direction:'out']).call()
    def prod = ec.entity.find('mantle.product.Product').condition('productId', li.productId).one()
    if (prod.enableBatchTracking == 'Y') {
        def src = allocations[li.transferItemSeqId][0].asset
        li.fromAssetId = src.assetId; li.batchNumber = src.batchNumber; li.update()
    }
    def pick = serialPicks[li.transferItemSeqId]
    if (pick) for (sn in pick.serials) {
        if (!pick.hadPicks) ec.service.sync().name('create#zenith.erp.inventory.StockTransferItemSerial').parameters([
            stockTransferId:stockTransferId, transferItemSeqId:li.transferItemSeqId, serialNumberId:sn.serialNumberId, serialNumber:sn.serialNumber]).call()
        sn.statusId = 'SnInTransit'; sn.update()
        ec.entity.makeValue('zenith.erp.inventory.SerialNumberHistory').setAll([
            serialNumberId:sn.serialNumberId, eventDate:ec.user.nowTimestamp, eventType:'Transfer ship', fromStatusId:'SnInStock', toStatusId:'SnInTransit',
            fromFacilityId:stx.fromFacilityId, referenceType:'StockTransfer', referenceId:stockTransferId, performedByUserId:ec.user.userId]).setSequencedIdPrimary().create()
    }
}
if (!ec.message.hasError()) ec.service.sync().name('zenith.inventory.InventoryServices.build#StockTransferIgstInvoice').parameters([stockTransferId:stockTransferId]).call()

def stx = guard.transfer
ec.entity.find('mantle.facility.Facility').condition('facilityId', stx.toFacilityId).forUpdate(true).one()
def items = ec.entity.find('zenith.erp.inventory.StockTransferItem').condition('stockTransferId', stockTransferId).orderBy('transferItemSeqId').list()
if (!items) { ec.message.addError('This transfer has no product lines.'); return }
def serials = [:]
for (li in items) {
    def qty = li.quantityReceived != null ? li.quantityReceived : li.quantity
    def prod = ec.entity.find('mantle.product.Product').condition('productId', li.productId).one()
    if (!prod || prod.ownerPartyId != guard.organizationPartyId || qty == null || qty < 0 || qty > li.quantity) { ec.message.addError('Invalid product or received quantity.'); continue }
    if (prod.enableBatchTracking == 'Y') {
        def src = ec.entity.find('mantle.product.asset.Asset').condition('assetId', li.fromAssetId).one()
        if (!src || src.ownerPartyId != guard.organizationPartyId || src.productId != li.productId || src.facilityId != stx.fromFacilityId || src.batchNumber != li.batchNumber) ec.message.addError('The original source batch is unavailable; the transfer cannot lose its batch identity.')
    }
    if (prod.enableSerialTracking == 'Y') {
        def rows = ec.entity.find('zenith.erp.inventory.StockTransferItemSerial').condition('stockTransferId', stockTransferId).condition('transferItemSeqId', li.transferItemSeqId).list()
        def arrived = rows.findAll { it.received == 'Y' || (it.received == null && qty == li.quantity) }.collect { it.serialNumberId }.toSet()
        if (qty.stripTrailingZeros().scale() > 0 || rows.size() != li.quantity.intValueExact() || arrived.size() != qty.intValueExact()) { ec.message.addError('Confirm exactly which serial numbers arrived before receiving a partial serialized transfer.'); continue }
        def sns = rows.collect { ec.entity.find('zenith.erp.inventory.ProductSerialNumber').condition('serialNumberId', it.serialNumberId).forUpdate(true).one() }
        if (sns.any { !it || it.productId != li.productId || it.facilityId != stx.fromFacilityId || !(it.statusId in ['SnInTransit','SnInStock']) }) ec.message.addError('A shipped serial number has changed location or status.')
        serials[li.transferItemSeqId] = [units:sns, arrived:arrived]
    }
}
if (ec.message.hasError()) return
for (li in items) {
    def qty = li.quantityReceived != null ? li.quantityReceived : li.quantity
    def prod = ec.entity.find('mantle.product.Product').condition('productId', li.productId).one()
    def src = li.fromAssetId ? ec.entity.find('mantle.product.asset.Asset').condition('assetId', li.fromAssetId).one() : null
    def target = null
    if (qty > 0) {
        def find = ec.entity.find('mantle.product.asset.Asset').condition('ownerPartyId', guard.organizationPartyId).condition('productId', li.productId)
            .condition('facilityId', stx.toFacilityId).condition('assetTypeEnumId', 'AstTpInventory').condition('batchNumber', li.batchNumber ?: null).orderBy('assetId').forUpdate(true)
        // Equal batch names with different expiry/manufacture dates must remain separate lots.
        if (prod.enableBatchTracking == 'Y') find.condition('expiryDate', src.expiryDate).condition('manufacturingDate', src.manufacturingDate)
        target = find.one()
        if (!target) target = ec.entity.makeValue('mantle.product.asset.Asset').setAll([
            assetTypeEnumId:'AstTpInventory', statusId:'AstAvailable', ownerPartyId:guard.organizationPartyId, productId:li.productId,
            facilityId:stx.toFacilityId, hasQuantity:'Y', quantityOnHandTotal:0G, availableToPromiseTotal:0G,
            batchNumber:li.batchNumber, expiryDate:src?.expiryDate, manufacturingDate:src?.manufacturingDate,
            mrpAmount:src?.mrpAmount, valuationRate:src?.valuationRate]).setSequencedIdPrimary().create()
        ec.service.sync().name('zenith.inventory.StockTransferServices.move#StockTransferAsset').parameters([
            stockTransferId:stockTransferId, assetId:target.assetId, quantityDiff:qty, direction:'in']).call()
    }
    def pick = serials[li.transferItemSeqId]
    if (pick) for (sn in pick.units) {
        def arrived = pick.arrived.contains(sn.serialNumberId)
        def oldStatus = sn.statusId
        sn.statusId = arrived ? 'SnInStock' : 'SnTransferLost'
        if (arrived) { sn.facilityId = stx.toFacilityId; sn.assetId = target.assetId }
        sn.update()
        ec.entity.makeValue('zenith.erp.inventory.SerialNumberHistory').setAll([
            serialNumberId:sn.serialNumberId, eventDate:ec.user.nowTimestamp, eventType:arrived ? 'Transfer receive' : 'Transfer loss',
            fromStatusId:oldStatus, toStatusId:sn.statusId, fromFacilityId:stx.fromFacilityId, toFacilityId:arrived ? stx.toFacilityId : null,
            referenceType:'StockTransfer', referenceId:stockTransferId, performedByUserId:ec.user.userId]).setSequencedIdPrimary().create()
    }
    li.quantityReceived = qty; li.update()
}
if (!ec.message.hasError()) {
    def header = ec.entity.find('zenith.erp.inventory.StockTransfer').condition('stockTransferId', stockTransferId).one()
    header.statusId = 'StxReceived'; header.update()
}
